const event = $json.event || $json;
const source = event.source || {};
const message = event.message || {};
const text = message.text || '';
const mentionees = message.mention?.mentionees || [];
const mentionedSelf = mentionees.some((item) => item.isSelf === true);
const isGroup = source.type === 'group' || source.type === 'room';
const asksTodos = /待辦|工單|今天|急件|todo/i.test(text);

return [{
  json: {
    ...$json,
    isGroupTodoQuery: isGroup && mentionedSelf && asksTodos,
    replyToken: event.replyToken,
    groupId: source.groupId || source.roomId || '',
    userId: source.userId || '',
    cleanText: text.replace(/@\S+/g, '').trim(),
    today: new Date().toISOString().slice(0, 10),
  },
}];

