const results = $json.results || [];
const priorityRank = { '急件': 0, '今天需回覆': 1, '一般': 2 };

const tickets = results
  .map((page) => {
    const props = page.properties || {};
    return {
      title: props['工單標題']?.title?.[0]?.plain_text || '未命名工單',
      priority: props['急迫度']?.select?.name || '一般',
      owner: props['負責人']?.rich_text?.[0]?.plain_text || '未指派',
      mentionUserId: props['LINE Mention User ID']?.rich_text?.[0]?.plain_text || '',
      customer: props['客戶名稱']?.rich_text?.[0]?.plain_text || '',
      note: props['問題說明']?.rich_text?.[0]?.plain_text || '',
    };
  })
  .sort((a, b) => priorityRank[a.priority] - priorityRank[b.priority]);

if (tickets.length === 0) {
  return [{ json: { messages: [{ type: 'text', text: '今天目前沒有未完成待辦。' }] } }];
}

const substitution = {};
const lines = ['今天待辦依急迫度整理：'];

tickets.forEach((ticket, index) => {
  const key = `u${index + 1}`;
  const ownerText = ticket.mentionUserId && ticket.mentionUserId.startsWith('U_') ? `{${key}}` : ticket.owner;
  lines.push(`${index + 1}. [${ticket.priority}] ${ticket.title}`);
  lines.push(`   負責：${ownerText}｜客戶：${ticket.customer || '未填'}`);
  if (ticket.note) lines.push(`   ${ticket.note.slice(0, 60)}`);

  if (ownerText === `{${key}}`) {
    substitution[key] = {
      type: 'mention',
      mentionee: { type: 'user', userId: ticket.mentionUserId },
    };
  }
});

const message = Object.keys(substitution).length
  ? { type: 'textV2', text: lines.join('\n'), substitution }
  : { type: 'text', text: lines.join('\n') };

return [{ json: { messages: [message] } }];
